const countryDialog=document.getElementById('countryDialog'),countryBrief=document.getElementById('countryBrief'),atlas=document.getElementById('atlasGrid');
const countryAliases={'Congo, Democratic Republic':'Democratic Republic of the Congo','Congo, Republic':'Republic of the Congo','Côte d’Ivoire':'Ivory Coast','Gambia':'The Gambia'};
function safeText(value){return String(value||'Not available').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function markCountryCards(){atlas.querySelectorAll('.country-card').forEach(card=>{card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label',`Open travel intelligence for ${card.querySelector('h3')?.textContent}`)})}
new MutationObserver(markCountryCards).observe(atlas,{childList:true});markCountryCards();
atlas.addEventListener('click',e=>{const card=e.target.closest('.country-card');if(card)openCountryBrief(card.querySelector('h3').textContent)});
atlas.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.country-card')){e.preventDefault();openCountryBrief(e.target.querySelector('h3').textContent)}});
document.querySelector('.country-close').addEventListener('click',()=>countryDialog.close());
async function openCountryBrief(country){countryDialog.showModal();countryBrief.innerHTML='<p class="database-status">Loading current country information…</p>';const lookup=countryAliases[country]||country,atlasRow=(window.africanAtlas||[]).find(x=>x[0]===country);try{const [countryResponse,wikiResponse]=await Promise.all([fetch(`https://restcountries.com/v3.1/name/${encodeURIComponent(lookup)}?fullText=true`),fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(lookup)}`)]),countryData=(await countryResponse.json())[0],wiki=await wikiResponse.json(),code=countryData.cca2,popResponse=await fetch(`https://api.worldbank.org/v2/country/${code}/indicator/SP.POP.TOTL?format=json&mrnev=1`),popData=await popResponse.json(),population=popData?.[1]?.[0]?.value||countryData.population,capital=(countryData.capital||[]).join(', '),currencies=Object.values(countryData.currencies||{}).map(x=>x.name).join(', '),languages=Object.values(countryData.languages||{}).join(', '),government=wiki.extract||'Open the official sources below for current political and security information.',searchCountry=encodeURIComponent(country);countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">Country intelligence</p><h2>${safeText(country)}</h2><p>${safeText(countryData.region)} · ${safeText(countryData.subregion)}</p></div><div class="country-facts"><div><small>Capital</small><strong>${safeText(capital)}</strong></div><div><small>Population</small><strong>${Number(population).toLocaleString()}</strong></div><div><small>Currency</small><strong>${safeText(currencies)}</strong></div><div><small>Languages</small><strong>${safeText(languages)}</strong></div><div><small>Driving side</small><strong>${safeText(countryData.car?.side)}</strong></div><div><small>Calling code</small><strong>${safeText((countryData.idd?.root||'')+(countryData.idd?.suffixes?.[0]||''))}</strong></div></div><section class="brief-section"><h3>Where to go</h3><p>${safeText(atlasRow?.[2]||'Destination information is being expanded.')}</p></section><section class="brief-section"><h3>Political and social context</h3><p>${safeText(government)}</p></section><section class="brief-section"><h3>Current travel and security advice</h3><p style="margin-bottom:10px">Conditions, entry rules and political risks change. Check live government advisories before booking or crossing a border.</p><div class="advisory-links"><a href="https://www.gov.uk/search/all?keywords=${searchCountry}%20travel%20advice">UK travel advice ↗</a><a href="https://travel.state.gov/content/travel/en/search.html?search_input=${searchCountry}">US travel advisory ↗</a></div></section><div class="brief-updated">Live facts retrieved ${new Date().toLocaleString()}. Population source: World Bank where available. Country facts: REST Countries. Overview: Wikipedia. Verify visas, health rules and security conditions with official authorities.</div>`}catch(e){countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">Country intelligence</p><h2>${safeText(country)}</h2></div><section class="brief-section"><h3>Where to go</h3><p>${safeText(atlasRow?.[2])}</p></section><section class="brief-section"><h3>Live brief unavailable</h3><p>Connect to the internet and try again. The destination guide remains available offline.</p></section>`}}
